gtY(){return"\ubd84\uc11d \uc2dc\uac04"},
gtZ(){return"0.5-5\ucd08 \uc815\uc0c1"},
gu_(){return"\uc2e0\ub8b0\ub3c4"},
guf(){return"\ub0ae\uc74c"},
gud(){return"\ub192\uc74c"},
gug(){return"\uac80\ud1a0 \ud544\uc694"},
