gqg(){return"PDF / CSV / JSON / PNG \ub0b4\ubcf4\ub0b4\uae30"},
gpu(){return"\ubaa8\ub378 \ub2e4\uc6b4\ub85c\ub4dc \ubc0f \uc870\uc815 \uac00\uc774\ub4dc\uff08\ucd08\ubcf4\uc790\uc6a9\uff09"},
